import os, pathlib, tempfile
HERE = os.path.dirname(os.path.abspath(__file__)); os.chdir(HERE)
APP = pathlib.Path(HERE).parent.joinpath('inkling.html').as_uri()
import asyncio
from playwright.async_api import async_playwright
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); pg = await b.new_page(viewport={'width':1440,'height':900})
        errs=[]; pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.add_init_script(open('mock_lang.js').read())
        await pg.goto(APP); await pg.wait_for_timeout(900)
        await pg.click('#newNotebook'); await pg.fill('.modal input.field', 'K'); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(300)
        await (await pg.query_selector_all('.kind'))[2].click(); await pg.fill('.modal input.field', 'Brett'); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(600)
        await pg.click('#rail button[aria-pressed="true"]'); await pg.wait_for_timeout(200)
        for t in ['Bleibt da', 'Wandert mit']:
            await pg.mouse.click(1250, 760); await pg.click('#dock button[aria-label="Note box (N)"]'); await pg.keyboard.type(t); await pg.keyboard.press('Escape'); await pg.wait_for_timeout(150)
        note = lambda t: pg.evaluate(f"(()=>{{const n=[...document.querySelectorAll('.obj-note')].find(n=>n.innerText.includes('{t}')); const r=n.getBoundingClientRect(); return [Math.round(r.x), Math.round(r.y), Math.round(r.width), n.closest('.pinlayer')?'pinned':'page']}})()")
        a = await note('Bleibt da')
        await pg.mouse.click(a[0]+20, a[1]+10, button='right'); await pg.wait_for_timeout(200)
        await pg.click('.menu button:has-text("Stay in place on screen")'); await pg.wait_for_timeout(300)
        p0, q0 = await note('Bleibt da'), await note('Wandert mit')
        print('pinned:', p0)
        await pg.mouse.move(700, 450); await pg.mouse.wheel(0, 300); await pg.wait_for_timeout(150)
        for _ in range(3): await pg.keyboard.down('Control'); await pg.mouse.wheel(0, 120); await pg.keyboard.up('Control')
        await pg.wait_for_timeout(200)
        p1, q1 = await note('Bleibt da'), await note('Wandert mit')
        print('after scrolling and zooming out: pinned note', p0[:3], '->', p1[:3], '| page note', q0[:3], '->', q1[:3])
        await pg.mouse.move(p1[0]+30, p1[1]+10); await pg.mouse.down(); await pg.mouse.move(p1[0]+230, p1[1]+110, steps=6); await pg.mouse.up(); await pg.wait_for_timeout(200)
        p2 = await note('Bleibt da'); print('dragged pinned note to:', p2[:2])
        await pg.mouse.click(p2[0]+30, p2[1]+10, button='right'); await pg.wait_for_timeout(200)
        await pg.click('.menu button:has-text("Unpin")'); await pg.wait_for_timeout(300)
        p3 = await note('Bleibt da'); print('unpinned:', p3, '(same spot and size on screen)')
        await pg.mouse.move(700, 450); await pg.mouse.wheel(0, -200); await pg.wait_for_timeout(150)
        print('after unpin it scrolls with the page again:', (await note('Bleibt da'))[:2])
        # endless page: pin, then scroll the page
        await pg.click('.t-row.top .t-acts button'); await pg.click('.menu button:has-text("New page")'); await pg.wait_for_timeout(200)
        await (await pg.query_selector_all('.kind'))[1].click(); await pg.fill('.modal input.field', 'Lang'); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(500)
        await pg.click('.flow'); await pg.keyboard.type('Ich habe heute keine zeit weil ich muss lernen. ' * 3)
        for _ in range(30): await pg.keyboard.press('Enter')
        await pg.keyboard.type('Ende.')
        await pg.click('#dock button[aria-label="Note box (N)"]'); await pg.keyboard.type('Fixiert'); await pg.keyboard.press('Escape'); await pg.wait_for_timeout(700)
        f0 = await note('Fixiert'); await pg.mouse.click(f0[0]+20, f0[1]+10, button='right'); await pg.wait_for_timeout(200)
        if False: print('DEBUG scroller', await pg.evaluate("(()=>{const s=document.querySelector('.scroller'); return [s.scrollTop, s.scrollHeight, s.clientHeight, getComputedStyle(s).overflowY, s.getBoundingClientRect().bottom]})()"), '| note', f0, '| editing:', await pg.evaluate("!!document.querySelector('.obj-note.editing')"), '| menu:', await pg.evaluate("[...document.querySelectorAll('.menu button,.menu .mlabel')].map(b=>b.innerText.trim())"), '| at point:', await pg.evaluate(f"(()=>{{const e=document.elementFromPoint({f0[0]+20},{f0[1]+10}); return e.className}})()"))
        await pg.click('.menu button:has-text("Stay in place on screen")'); await pg.wait_for_timeout(300)
        f1 = await note('Fixiert'); await pg.evaluate("document.querySelector('.scroller').scrollTop += 400"); await pg.wait_for_timeout(200)
        print('endless page scrolled 400px: pinned note', f1[:2], '->', (await note('Fixiert'))[:2])
        await pg.evaluate("document.querySelector('.scroller').scrollTop = 0"); await pg.wait_for_timeout(200)
        # Magic box: Language group, cog, search
        await pg.click('#dock .magic-go'); await pg.wait_for_timeout(300)
        print('magic Language rows:', await pg.evaluate("[...document.querySelectorAll('.pop .sw-row')].map(r=>r.innerText.replace(/\\n/g,' ').trim()).filter(t=>/Auto/.test(t))"))
        await pg.click('.pop .sw-row:has-text("Auto-correct") .lang-cog'); await pg.wait_for_timeout(200)
        print('picker: first items', await pg.evaluate("[...document.querySelectorAll('.langpop .lp-item')].slice(0,4).map(b=>b.innerText.replace(/\\n/g,' '))"), '| total', await pg.evaluate("document.querySelectorAll('.langpop .lp-item').length"), '| scrolls:', await pg.evaluate("(()=>{const l=document.querySelector('.langpop .lp-list'); return l.scrollHeight > l.clientHeight})()"))
        await pg.keyboard.type('deut'); await pg.wait_for_timeout(100)
        print('search "deut":', await pg.evaluate("[...document.querySelectorAll('.langpop .lp-item')].map(b=>b.innerText.replace(/\\n/g,' '))"))
        await pg.keyboard.press('Enter'); await pg.wait_for_timeout(200)
        print('cog now:', await pg.inner_text('.pop .sw-row:has-text("Auto-correct") .lang-cog'), '| magic pop still open:', await pg.evaluate("!!document.querySelector('.pop .sw-row')"))
        await pg.click('.pop .sw-row:has-text("Auto-correct") .sw, .pop .sw-row:has-text("Auto-correct") [role=switch]'); await pg.wait_for_timeout(200)
        for k in ['Tidy text', 'Tidy layout', 'Tidy drawings']:
            on = await pg.evaluate(f"(()=>{{const r=[...document.querySelectorAll('.pop .sw-row')].find(r=>r.innerText.includes('{k}')); const s=r&&r.querySelector('[role=switch]'); return s ? s.getAttribute('aria-checked') : null}})()")
            if on == 'true': await pg.click(f'.pop .sw-row:has-text("{k}") [role=switch]'); await pg.wait_for_timeout(120)
        await pg.click('.pop button:has-text("Drag a box now")'); await pg.wait_for_timeout(200)
        fl = await (await pg.query_selector('.flow')).bounding_box()
        await pg.mouse.move(fl['x']+5, fl['y']+5); await pg.mouse.down(); await pg.mouse.move(fl['x']+fl['width']-10, fl['y']+80, steps=6); await pg.mouse.up(); await pg.wait_for_timeout(1500)
        pr = await pg.evaluate("window.__prompts.filter(p=>p.includes('Correct spelling'))")
        print('Magic auto-correct asked the AI:', [x[x.index('Correct spelling'):x.index('Correct spelling')+120] for x in pr][:1])
        # Tidy up: Auto-translate with a cog
        await pg.keyboard.press('Escape'); await pg.mouse.click(1300, 300)
        tab = await pg.evaluate("(()=>{for (const t of ['Home','Insert','Draw','Magic box','Fact check','View']) { const b=[...document.querySelectorAll('.rtabs button')].find(x=>x.innerText.trim()===t); if (b) { b.click(); if (document.querySelector('#ribbon button[aria-label=\"Tidy up\"]')) return t; } } return null})()")
        print('Tidy up is in the tab:', tab)
        await pg.click('#ribbon button[aria-label="Tidy up"]'); await pg.wait_for_timeout(300)
        print('tidy options:', await pg.evaluate("[...document.querySelectorAll('.modal .checks label > span')].map(s=>s.firstChild.textContent)"))
        await pg.click('.modal .check-cog:has-text("Auto-translate") .lang-cog'); await pg.wait_for_timeout(200)
        await pg.keyboard.type('franz'); await pg.wait_for_timeout(100)
        print('search franz:', await pg.evaluate("[...document.querySelectorAll('.langpop .lp-item')].map(b=>b.innerText.replace(/\\n/g,' '))"))
        await pg.fill('.langpop .lp-search', 'kurd'); await pg.wait_for_timeout(100)
        print('search kurd:', await pg.evaluate("[...document.querySelectorAll('.langpop .lp-item')].map(b=>b.innerText.replace(/\\n/g,' '))"))
        await pg.fill('.langpop .lp-search', 'franz'); await pg.wait_for_timeout(100)
        await pg.click('.langpop .lp-item:has-text("French")'); await pg.wait_for_timeout(150)
        print('Tidy shares the Auto-correct language with the Magic box:', await pg.inner_text('.modal .check-cog:has-text("Auto-correct") .lang-cog'))
        await pg.click('.modal label:has-text("Auto-translate") input'); 
        for k in ['Layout']:
            c = await pg.query_selector(f'.modal label:has-text("{k}") input')
            if c and await c.is_checked(): await c.click()
        await pg.evaluate("window.__prompts = []")
        await pg.click('.modal .btn.primary:has-text("Tidy up")'); await pg.wait_for_timeout(2000)
        pr = await pg.evaluate("window.__prompts.filter(p=>p.includes('translate all of the text'))")
        print('Tidy auto-translate asked the AI:', [x[x.index('translate all of the text'):x.index('translate all of the text')+45] for x in pr][:1], '| also correct in German:', any('rules of German' in x for x in pr))
        print('ERRORS', errs[:5])
        await b.close()
asyncio.run(main())
